using System.IO.Ports;
var b=WebApplication.CreateBuilder(args);b.Services.AddSingleton<DualState>();b.Services.AddHostedService<DualWorker>();var a=b.Build();a.UseDefaultFiles();a.UseStaticFiles();a.MapGet("/api/telemetry",(DualState s)=>Results.Ok(s.Snapshot()));a.MapGet("/api/status",()=>Results.Ok(new{gateway="Kestrel Dual-Channel IoT Gateway",studentId="67030154",time=DateTime.UtcNow}));a.Run();
public sealed class DualState{readonly object g=new();int x=3268,y=2048;public void Set(int a,int b){lock(g){x=Math.Clamp(a,0,4095);y=Math.Clamp(b,0,4095);}}public object Snapshot(){lock(g){return new{studentId="67030154",channelA=new{name="ESP32 Potentiometer",rawValue=x,percentage=Math.Round(x/4095d*100,1)},channelB=new{name="Sensor B (simulated)",rawValue=y,percentage=Math.Round(y/4095d*100,1)},dataSource="Live ESP32 + Simulation"};}}}
public sealed class DualWorker:BackgroundService{readonly DualState s;public DualWorker(DualState x)=>s=x;protected override async Task ExecuteAsync(CancellationToken c){while(!c.IsCancellationRequested){var t=DateTime.UtcNow.TimeOfDay.TotalSeconds;var ports=SerialPort.GetPortNames();if(ports.Length>0)try{using var p=new SerialPort(ports[0],115200);p.Open();if(int.TryParse(p.ReadLine().Trim(),out var a))s.Set(a,(int)((Math.Cos(t*1.1)+1)*2047.5));}catch{}else s.Set((int)((Math.Sin(t)+1)*2047.5),(int)((Math.Cos(t*1.1)+1)*2047.5));await Task.Delay(100,c);}}}